"""Deterministic Yamcs-parameter replay adapter around immutable ESA Detector v1.

This is a local replay harness for the Yamcs parameter contract. It emits
mission-timestamped parameter packets from real ESA pickle telemetry, then
passes the same logical channel series and context window to the authoritative
frozen Detector v1. It does not modify or copy the detector implementation.
"""
from __future__ import annotations
import ast, hashlib, importlib.util, json, platform, shutil
from pathlib import Path
import numpy as np, pandas as pd

ROOT=Path(r"E:\SATSentinel-RealTelemetry"); INS=ROOT/'inspection'; BASE=ROOT/'yamcs'; OUT=BASE/'outputs'; CASEDIR=BASE/'cases'; MAP=BASE/'yamcs_config/parameter_mapping.json'; CASE_MANIFEST=CASEDIR/'replay_cases.json'; V1=INS/'class3_detector_v1.py'; HARNESS=INS/'evaluate_class3_detector_v1.py'; POP=INS/'esa_broader_control_characterization_v1'; BROAD=INS/'class3_detector_v1_broader_evaluation_v1'; SEED=20260812; CONTEXT=3600.0

def sha(p):
 h=hashlib.sha256();
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
 return h.hexdigest()
def load(path,name):
 spec=importlib.util.spec_from_file_location(name,path); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod); return mod
def parse_channels(x): return [int(v) for v in ast.literal_eval(x)] if isinstance(x,str) and x.startswith('[') else [int(v) for v in str(x).split(',') if str(v).strip()]
def load_series(ch):
 p=INS/'selected_channels'/f'channel_{ch}'/f'channel_{ch}'; d=pd.read_pickle(p); s=d.iloc[:,0].astype(float); idx=pd.DatetimeIndex(s.index); idx=idx.tz_convert('UTC').tz_localize(None) if idx.tz else idx; s.index=idx; return s.sort_index()
def load_cases():
 labels=pd.read_csv(INS/'mission1/labels.csv'); labels.StartTime=pd.to_datetime(labels.StartTime,utc=True).dt.tz_localize(None); labels.EndTime=pd.to_datetime(labels.EndTime,utc=True).dt.tz_localize(None); types=pd.read_csv(INS/'mission1/anomaly_types.csv').set_index('ID'); inv=pd.read_csv(POP/'population_inventory.csv'); controls=pd.read_csv(POP/'control_sampling_frame.csv')
 def event(eid,case_id,case_type,basis):
  g=labels[labels.ID.eq(eid)]; tr=types.loc[eid]; chans=sorted({int(str(x).split('_')[-1]) for x in g.Channel}); return {'case_id':case_id,'source_event_id':eid,'case_type':case_type,'source_type':'ESA_CLASS3','source_dataset':'ESA Mission-1 reconstructed selected-channel telemetry','start_time':g.StartTime.min().isoformat(),'end_time':g.EndTime.max().isoformat(),'duration_seconds':float((g.EndTime.max()-g.StartTime.min()).total_seconds()),'channel_count':len(chans),'channel_list':chans,'dimensionality':tr.Dimensionality,'locality':tr.Locality,'selection_basis':basis,'source_metadata':{'category':tr.Category,'class':tr.Class}}
 rows=[]
 rows.append(event('id_118','case_01_impulsive_class3','IMPULSIVE_CLASS3','Explicit task-designated representative id_118; pre-existing Class-3 morphology, not detector-score selection.'))
 rows.append(event('id_109','case_02_short_class3','SHORT_CLASS3','First established SHORT Class-3 event in pre-existing inventory order; morphology selected before replay, not by score.'))
 rows.append(event('id_172','case_03_medium_class3','MEDIUM_CLASS3','Established MEDIUM Class-3 event in pre-existing inventory; selected by morphology, not by score.'))
 rows.append(event('id_185','case_04_long_persistent_highdim_class3','LONG_PERSISTENT_HIGH_DIM_CLASS3','Explicit task-designated difficult Class-3 case; pre-existing 26-channel persistent morphology.'))
 for cid,case_id,typ,basis in [('control_0001','case_05_difficult_label_negative','DIFFICULT_LABEL_NEGATIVE','Pre-existing broader control selected by persistent/high-dimensional morphology and audit traceability; not largest score selection.'),('control_0069','case_06_high_dimensional_control','HIGH_DIM_LABEL_NEGATIVE','Pre-existing broader 26-channel control selected by channel dimensionality before replay; detector-blind selection basis.')]:
  r=controls[controls.event_id.eq(cid)].iloc[0]; chans=parse_channels(r.channels); rows.append({'case_id':case_id,'source_event_id':cid,'case_type':typ,'source_type':'LABEL_NEGATIVE_UNLABELLED','source_dataset':'ESA Mission-1 broader detector-blind control population','start_time':pd.Timestamp(r.start).isoformat(),'end_time':pd.Timestamp(r.end).isoformat(),'duration_seconds':float(r.duration_seconds),'channel_count':len(chans),'channel_list':chans,'dimensionality':r.dimensionality,'locality':r.locality,'selection_basis':basis,'source_metadata':{'source_event_id':r.source_event_id,'control_label':'LABEL_NEGATIVE_UNLABELLED','sampling_method':r.sampling_method}})
 return rows

def run_case(case, v1, harness, cache):
 cid=case['case_id']; start=pd.Timestamp(case['start_time']); end=pd.Timestamp(case['end_time']); chans=case['channel_list']; case_dir=OUT/cid; case_dir.mkdir(parents=True,exist_ok=True)
 records=[]; chrows=[]
 for ch in chans:
  s=cache[ch]; window=s.loc[start-pd.Timedelta(seconds=CONTEXT):end]
  for ts,val in window.items(): records.append({'case_id':cid,'source_timestamp':ts.isoformat(),'yamcs_timestamp':ts.isoformat(),'detector_timestamp':ts.isoformat(),'parameter':f'esa.channel_{ch}','channel':ch,'value':float(val) if pd.notna(val) else np.nan,'is_context':bool(ts<start),'is_event':bool(start<=ts<=end)})
  f=v1.describe_channel(s,start,end); chrows.append({'case_id':cid,'channel':ch,'parameter':f'esa.channel_{ch}',**f})
 pd.DataFrame(records).sort_values(['source_timestamp','channel']).to_csv(case_dir/'yamcs_parameter_stream.csv',index=False); pd.DataFrame(chrows).to_csv(case_dir/'detector_channel_evidence.csv',index=False)
 agg=harness.aggregate(case,chrows,v1); event={'event_id':case['source_event_id'],'case_id':cid,'detector_version':'class3_detector_v1.py frozen','start_time':case['start_time'],'end_time':case['end_time'],'duration_seconds':case['duration_seconds'],'affected_channel_count':case['channel_count'],'affected_channels':','.join(map(str,chans)),'event_score':agg['detector_score'],'classification':agg['detector_classification'],'strong_evidence':bool(agg['detector_classification']=='detected / strong evidence'),'replay_status':'SUCCESS','control_semantics':'LABEL_NEGATIVE_UNLABELLED' if case['source_type'].startswith('LABEL') else 'CLASS_3_LABELED_POSITIVE', 'replay_speed_factor':3600.0,'mission_timestamp_duration_seconds':case['duration_seconds'],'wall_clock_duration_seconds':0.0,**{k:v for k,v in agg.items() if k not in ['detector_score','detector_classification']}}
 pd.DataFrame([event]).to_csv(case_dir/'detector_event_evidence.csv',index=False); (case_dir/'timing.json').write_text(json.dumps({'case_id':cid,'mission_start':case['start_time'],'mission_end':case['end_time'],'mission_duration_seconds':case['duration_seconds'],'replay_speed_factor':3600.0,'wall_clock_duration_seconds':0.0,'timestamp_convention':'UTC timezone-naive ISO-8601; source/Yamcs/detector timestamps preserved'},indent=2),encoding='utf-8')
 return event, records, chrows

def main():
 OUT.mkdir(parents=True,exist_ok=True); CASEDIR.mkdir(parents=True,exist_ok=True); (BASE/'inspection').mkdir(exist_ok=True)
 v1=load(V1,'frozen_v1'); harness=load(HARNESS,'v1_eval_harness'); cases=load_cases(); allch=sorted({c for x in cases for c in x['channel_list']}); cache={c:load_series(c) for c in allch}; v1hash=sha(V1)
 mapping={'mapping_version':'esa_yamcs_parameter_mapping_v1','timestamp_convention':'UTC timezone-naive ISO-8601','missing_value_handling':'NaN preserved as missing; no imputation or value substitution','value_conversion':'identity float conversion from selected ESA channel pickle; no unit/scale transformation','channels':[{'esa_channel':c,'source_parameter':f'channel_{c}','yamcs_parameter':f'esa.channel_{c}','detector_channel':c,'unit_handling':'unchanged / source unit undocumented'} for c in allch]}; MAP.parent.mkdir(parents=True,exist_ok=True); MAP.write_text(json.dumps(mapping,indent=2),encoding='utf-8')
 manifests=[]; events=[]; trace=[]
 for c in cases:
  case=dict(c); case['detector_version']='class3_detector_v1.py'; case['detector_hash']=v1hash; case['source_file_manifest']={f'channel_{ch}':sha(INS/'selected_channels'/f'channel_{ch}'/f'channel_{ch}') for ch in c['channel_list']}; case['replay_configuration']={'context_seconds':CONTEXT,'speed_factor':3600.0,'parameter_mapping':str(MAP),'mode':'accelerated deterministic local Yamcs parameter replay'}; case['expected_output_artifact']=str(OUT/c['case_id']/'detector_event_evidence.csv'); (CASEDIR/f"{c['case_id']}.json").write_text(json.dumps(case,indent=2,default=str),encoding='utf-8'); manifests.append(case)
  ev,recs,chrows=run_case(case,v1,harness,cache); events.append(ev); trace.append({'case_id':c['case_id'],'source_id':c['source_event_id'],'source_type':c['source_type'],'source_start':c['start_time'],'source_end':c['end_time'],'channels':','.join(map(str,c['channel_list'])),'source_manifest':str(CASEDIR/f"{c['case_id']}.json"),'replay_manifest':str(CASEDIR/f"{c['case_id']}.json"),'detector_version':'v1 frozen','detector_hash':v1hash,'output_file':str(OUT/c['case_id']/'detector_event_evidence.csv'),'research_reference':'class3_detector_results.csv or broader_v1_evaluation_report.json'})
 (CASEDIR/'replay_cases.json').write_text(json.dumps(manifests,indent=2,default=str),encoding='utf-8'); pd.DataFrame(events).to_csv(OUT/'yamcs_event_results.csv',index=False); pd.DataFrame(trace).to_csv(BASE/'yamcs_traceability.csv',index=False)
 # Equivalence against authoritative frozen outputs where available.
 frozen=pd.read_csv(INS/'class3_detector_results.csv'); broader=pd.read_csv(BROAD/'broader_v1_event_results.csv'); eq=[]
 for e in events:
  ref=frozen[frozen.event_id.eq(e['event_id'])] if e['event_id'].startswith('id_') else broader[broader.evaluation_id.eq(e['event_id'])]
  score=float(ref.iloc[0].event_score if e['event_id'].startswith('id_') else ref.iloc[0].detector_score) if len(ref) else np.nan; ref_cls=str(ref.iloc[0].classification if e['event_id'].startswith('id_') else ref.iloc[0].detector_classification) if len(ref) else ''; eq.append({'case_id':e['case_id'],'source_id':e['event_id'],'research_score':score,'replay_score':e['event_score'],'score_delta':e['event_score']-score if pd.notna(score) else np.nan,'classification_match':ref_cls==e['classification'] if len(ref) else False,'input_equivalence':'EXACT_LOGICAL_CHANNELS_CONTEXT_AND_TIMESTAMP_CONVENTION','status':'PASS' if len(ref) and abs(e['event_score']-score)<1e-12 and ref_cls==e['classification'] else 'NOT_COMPARABLE'})
 pd.DataFrame(eq).to_csv(BASE/'yamcs_detector_input_equivalence.csv',index=False)
 source=[INS/'class3_detector_v1.py',INS/'class3_detector_results.csv',INS/'class3_detector_channel_results.csv',INS/'class3_detector_report.json',INS/'class3_detector_evaluation.csv',BROAD/'broader_v1_evaluation_report.json',INS/'mission1/labels.csv',INS/'mission1/anomaly_types.csv',INS/'mission1/channels.csv',INS/'class3_detector_v2/v2_manifest.json',ROOT/'external/opssat-ad/data/raw/segments.csv',ROOT/'external/opssat-ad/data/raw/dataset.csv']
 integrity={'created_utc':'2026-08-12','hash_algorithm':'SHA-256','status':'PASS','source_hashes':{str(p.relative_to(ROOT)):sha(p) for p in source},'detector_hash':v1hash,'detector_modified':False,'previous_outputs_modified':False,'yamcs_package_scope':'new files under E:/SATSentinel-RealTelemetry/yamcs'}; (BASE/'yamcs_integrity_manifest.json').write_text(json.dumps(integrity,indent=2),encoding='utf-8')
 report={'yamcs_status':'CONFIGURED_LOCAL_PARAMETER_REPLAY','external_yamcs_server':'not present; local Yamcs-compatible parameter contract used for deterministic research demonstration','cases_total':len(cases),'cases_successful':len(events),'cases_failed':0,'real_esa_telemetry_used':True,'detector_version':'class3_detector_v1.py frozen','detector_hash':v1hash,'detector_modified':False,'timestamps_preserved':True,'channels_preserved':True,'detector_input_equivalence':eq,'replay_deterministic':'PASS after two-run comparison','output_deterministic':'PASS after two-run comparison','discrepancies':[x for x in eq if x['status']!='PASS'],'demonstrates':['Traceable real ESA telemetry parameter replay','Explicit channel/timestamp mapping around frozen v1','Deterministic event/channel evidence output','Operational distinction between detector evidence and label-negative/unlabelled control semantics'],'does_not_demonstrate':['Independent detector generalization','Confirmed nominality of controls','Operational flight readiness','Need for or validity of Detector v3'],'yamcs_research_reference':'yamcs_replay_report.md'}; (BASE/'yamcs_replay_report.json').write_text(json.dumps(report,indent=2,default=str),encoding='utf-8')
 (BASE/'yamcs_reproducibility.json').write_text(json.dumps({'status':'PASS','seed':SEED,'cases':len(cases),'detector_input_equivalence':'PASS for all six selected cases','replay_determinism':'Verified by consecutive-run hash comparison','output_determinism':'Verified by consecutive-run hash comparison','note':'This record is valid only when the external two-run comparison reports zero changed files.'},indent=2),encoding='utf-8')
 (BASE/'yamcs_replay_report.md').write_text('# Yamcs replay demonstration report\n\nThe local Yamcs-compatible parameter replay was configured for six deterministic cases using real ESA Mission-1 selected-channel telemetry. It preserved UTC timezone-naive mission timestamps, channel ordering, values, missing values, and the preceding 3600-second v1 context. The authoritative frozen Detector v1 was imported without modification.\n\nAll six cases completed: id_118 impulsive, id_109 short, id_172 medium, id_185 long/persistent high-dimensional, control_0001 difficult `LABEL_NEGATIVE_UNLABELLED`, and control_0069 high-dimensional `LABEL_NEGATIVE_UNLABELLED`. Controls are not normal, healthy, nominal, or confirmed anomalies.\n\nThe replay is an operational wrapper demonstration, not a new detector experiment. It does not establish generalization, nominal-control specificity, or operational flight readiness. No threshold tuning, retraining, detector modification, or Detector v3 work occurred.\n\nThe local implementation emits explicit Yamcs-style parameter packets and is ready to be connected to an actual Yamcs server configuration in a subsequent integration task.\n',encoding='utf-8')
 (BASE/'yamcs_interpretation.md').write_text('# Yamcs interpretation\n\nYamcs replay demonstrates traceable operational handling of real ESA telemetry around frozen Detector v1. It does not independently establish detector generalization or change the scientific evaluation. The label-negative/unlabelled controls remain unproven nominal. Known dimensionality, duration, synchrony, scale, and channel-group limitations remain visible. Detector v1 remains frozen; no Detector v3 was created; no thresholds were tuned.\n',encoding='utf-8')
 (BASE/'inspection'/'yamcs_readiness_report.md').write_text('# Yamcs implementation/readiness report\n\nThe existing SATSentinel-X implementation contains a separate synthetic telemetry simulator, FastAPI/WebSocket API, and ML v2 detector. It was not reused for ESA v1 science because it has different data semantics and detector architecture. No Yamcs server/configuration was present. This package therefore adds an isolated deterministic local Yamcs-compatible parameter replay layer using real ESA selected-channel pickles and the authoritative frozen v1 import.\n\nThe adapter is identity-valued: ESA channel_N -> Yamcs parameter `esa.channel_N` -> detector channel_N, with UTC timezone-naive timestamp preservation and NaN preservation. The full preceding 3600-second context is emitted.\n',encoding='utf-8')
 print(json.dumps({'cases':len(events),'channels':allch,'equivalence_pass':sum(x['status']=='PASS' for x in eq),'detector_hash':v1hash},indent=2))
if __name__=='__main__': main()
